// Issue #154 Phase 2-C2.6-B2-C2A-R1 Research only: the B2-C2A timeout subset, searched again with a longer budget (the
// Search children never read an oracle, the B2-C2A RESULT or any compatibility).
//
// Parent:
//   0. reads the Export, the B2-C2A validation Target manifest (--targets, regenerated by the existing
//      prepare-planner-global-phase2c26b2c2a-targets.mjs) and the retry manifest (--retry, made by
//      prepare-planner-global-phase2c26b2c2ar1-retry.mjs: task IDs and source hashes only). The Target manifest SHA-256 must
//      be the registered B2-C2A one, and the Export SHA-256 the one both manifests name;
//   1. `tasks` child: the UNCHANGED B2-C2A child (scripts/run-planner-global-phase2c26b2c2a.mjs --role tasks):
//      derivePhase2C26B2C1Schedule() over the Export, then buildPhase2C26B2C2ATasks(); 20 x 16 = 320 tasks or no Search runs;
//   2. selectPhase2C26B2C2AR1Tasks(): the retry task IDs only, each exactly once (2 / 320) or no Search runs;
//   3. retry: each selected task once in a fresh UNCHANGED B2-C2A search child (--role search: runPhase2C26B2C2ATask() ->
//      runPhase2C26B2C2ASearch() -> visitPlannerAlternativeCandidates()), heap 8 GB, concurrency 1, 30-minute budget, no
//      retry and no fallback. Only the budget and the concurrency differ from B2-C2A Stage 1.
// A child failure (timeout, out of memory, any other failure) is recorded as that failure, never as "no Candidate". The
// original 318 measured tasks are never re-run. Each child record stays in the run dir; the raw output names each record
// file and its SHA-256.
import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { existsSync, lstatSync, appendFileSync } from 'node:fs'
import { resolve, join, basename } from 'node:path'
import { createHash } from 'node:crypto'
import { spawn, execFileSync } from 'node:child_process'
import { cpus, totalmem, release, platform, arch } from 'node:os'
import { createServer } from 'vite'

const args = process.argv.slice(2)
const option = name => { const index = args.indexOf(name); return index < 0 ? undefined : args[index + 1] }
const exportPath = option('--export'), targetsPath = option('--targets'), retryPath = option('--retry'), runDir = option('--run-dir'), outputPath = option('--output')
if (!exportPath || !targetsPath || !retryPath || !runDir || !outputPath) {
  throw new Error('Usage: node scripts/run-planner-global-phase2c26b2c2ar1.mjs --export <external.json> --targets <B2-C2A targets manifest .json.local> --retry <retry manifest .json.local> --run-dir <new dir .local> --output <new.json.local> [--allow-uncommitted --smoke-budget-ms N --smoke-task-ids a,b]')
}
/** The unchanged B2-C2A child: the same tasks / search roles, the same modules, the same memory sampling. */
const CHILD_SCRIPT_PATH = 'scripts/run-planner-global-phase2c26b2c2a.mjs'
const write = (path, value, pretty = true) => writeFile(path, (pretty ? JSON.stringify(value, null, 2) : JSON.stringify(value)) + '\n', { flag: 'wx' })
const git = (...a) => execFileSync('git', a, { encoding: 'utf8' }).trim()
const sha256 = value => createHash('sha256').update(value).digest('hex')

if (resolve(exportPath).toLowerCase() === resolve(outputPath).toLowerCase()) throw new Error('Output must not overwrite the Export.')
if (lstatSync(outputPath, { throwIfNoEntry: false }) !== undefined) throw new Error(`Output already exists: ${resolve(outputPath)}`)
if (existsSync(runDir)) throw new Error(`Run dir already exists: ${resolve(runDir)}`)
const allowUncommitted = args.includes('--allow-uncommitted')
// Non-formal smoke only: a shorter budget and / or a named subset of the retry tasks.
const smokeBudgetMs = option('--smoke-budget-ms') === undefined ? null : Number(option('--smoke-budget-ms'))
const smokeTaskIds = option('--smoke-task-ids') === undefined ? null : option('--smoke-task-ids').split(',')
const smoke = smokeBudgetMs !== null || smokeTaskIds !== null
if (smoke && !allowUncommitted) throw new Error('--smoke-budget-ms / --smoke-task-ids are non-formal smoke options and need --allow-uncommitted.')

const codePaths = ['src', 'scripts', 'package.json', 'package-lock.json', 'vite.config.ts', 'tsconfig.json', 'tsconfig.app.json', 'tsconfig.node.json']
const uncommitted = Boolean(git('diff', 'HEAD', '--', ...codePaths) || git('ls-files', '--others', '--exclude-standard', '--', ...codePaths))
if (uncommitted && !allowUncommitted) throw new Error('Commit ALL benchmark code before a formal measurement (or pass --allow-uncommitted for a non-formal smoke).')
const codeHash = createHash('sha256')
for (const file of git('ls-files', '--', ...codePaths).split(/\r?\n/)) { codeHash.update(file + '\0'); codeHash.update(await readFile(file)); codeHash.update('\0') }
const benchmarkCodeSha256 = codeHash.digest('hex')
const rawExport = await readFile(exportPath)
const rawTargets = await readFile(targetsPath)
const rawRetry = await readFile(retryPath)

const server = await createServer({ configFile: false, server: { middlewareMode: true, watch: null, hmr: false }, appType: 'custom' })
try {
  const c2a = await server.ssrLoadModule('/src/benchmarks/plannerGlobalPhase2C26B2C2A.ts')
  const r1 = await server.ssrLoadModule('/src/benchmarks/plannerGlobalPhase2C26B2C2AR1.ts')
  const c26a = await server.ssrLoadModule('/src/benchmarks/plannerGlobalPhase2C26A.ts')
  const { ProductionRngEngine } = await server.ssrLoadModule('/src/domain/rng/production/productionRngEngine.ts')
  // 0. The manifests and the Export, before anything is written or run.
  const parsedTargets = c2a.parsePhase2C26B2C2ATargetManifest(JSON.parse(rawTargets.toString('utf8')))
  if (!parsedTargets.valid) throw new Error(`The Target manifest is not valid: ${parsedTargets.issues.join('; ')}`)
  const targets = parsedTargets.manifest
  if (sha256(rawTargets) !== r1.PHASE2C26B2C2AR1_SOURCE.targetManifestSha256) throw new Error('The Target manifest is not the registered B2-C2A Target manifest.')
  const parsedRetry = r1.parsePhase2C26B2C2AR1RetryManifest(JSON.parse(rawRetry.toString('utf8')))
  if (!parsedRetry.valid) throw new Error(`The retry manifest is not valid: ${parsedRetry.issues.join('; ')}`)
  const retry = parsedRetry.manifest
  if (retry.sourceTargetManifestSha256 !== sha256(rawTargets)) throw new Error('The retry manifest names another Target manifest.')
  if (sha256(rawExport) !== targets.exportSha256 || sha256(rawExport) !== retry.exportSha256) throw new Error('The Export read is not the one the manifests name.')

  await mkdir(runDir, { recursive: true })
  const processes = []
  const phaseStarted = performance.now()

  /** One fresh unchanged B2-C2A child. Resolves with its record (or null), its record file SHA-256, outcome and last IPC memory; never throws for a child failure. */
  const runChild = (id, childRole, task, { heapMb, budgetMs }) => new Promise(done => {
    const taskPath = join(runDir, `${id}.task.json`)
    const recordPath = join(runDir, `${id}.record.json`)
    const memoryPath = join(runDir, `${id}.memory.jsonl`)
    const nodeFlags = [`--max-old-space-size=${heapMb}`]
    const start = async () => {
      await write(taskPath, task)
      const childArgs = [...nodeFlags, CHILD_SCRIPT_PATH, '--role', childRole, '--export', exportPath, '--record', recordPath, '--task', taskPath]
      const began = performance.now(), startedAt = new Date().toISOString()
      let stderrTail = '', timedOut = false, killedAtMs = null, lastMemory = null, lastYields = 0, memoryMessages = 0
      const child = spawn(process.execPath, childArgs, { stdio: ['ignore', 'ignore', 'pipe', 'ipc'], windowsHide: true })
      // The budget is judged here, in the parent, never by the child.
      const timer = setTimeout(() => { timedOut = true; killedAtMs = performance.now() - began; child.kill('SIGKILL') }, budgetMs)
      child.stderr.on('data', chunk => { stderrTail = (stderrTail + chunk.toString()).slice(-12000) })
      child.on('message', message => {
        if (message?.type !== 'memory') return
        memoryMessages += 1
        lastMemory = message.maxima
        lastYields = message.yields
        if (memoryMessages % 20 === 1) appendFileSync(memoryPath, JSON.stringify({ receivedAtMs: performance.now() - began, ...message }) + '\n')
      })
      child.once('exit', async (code, signal) => {
        clearTimeout(timer)
        const recordWritten = existsSync(recordPath)
        const outcome = c26a.classifyPhase2C26AChildExit({ code, signal, timedOut, stderrTail, recordWritten })
        const entry = { id, role: childRole, outcome, exitCode: code, signal, timedOut, budgetMs, startedAt, wallMs: performance.now() - began, killedAtMs, nodeFlags,
          lastIpcMemory: lastMemory, lastIpcYields: lastYields, memoryMessages, stderrTail: outcome === 'completed' ? null : stderrTail.slice(-4000) }
        processes.push(entry)
        const recordRaw = outcome === 'completed' ? await readFile(recordPath) : null
        const record = recordRaw === null ? null : JSON.parse(recordRaw.toString('utf8'))
        const s = record?.result?.status === 'searched' ? record.result.search : null
        const status = s ? ` ${s.termination} n=${s.candidates.length} costs=${s.capturedCosts.join('/')}${s.nextCostSentinel ? ` sentinel=${s.nextCostSentinel.deliveryIndex}@${s.nextCostSentinel.orderingKeys.estimatedOperationCount}` : ''}`
          : record?.result?.status ? ` ${record.result.status}` : ''
        console.log(`${new Date().toISOString()} ${outcome.toUpperCase()} ${id}${status} ${(entry.wallMs / 1000).toFixed(1)}s heap<=${((lastMemory?.maxHeapUsedBytes ?? 0) / 2 ** 20).toFixed(0)}MB`)
        done({ entry, record, recordFile: recordRaw === null ? null : { file: basename(recordPath), bytes: recordRaw.length, sha256: sha256(recordRaw) } })
      })
    }
    start()
  })

  const retryConditions = { ...r1.PHASE2C26B2C2AR1_RETRY, budgetMs: smokeBudgetMs ?? r1.PHASE2C26B2C2AR1_RETRY.budgetMs }
  const environment = { runtime: 'Node (Vite SSR loader, one fresh unchanged B2-C2A child process per task, NOT a Browser Worker)', node: process.version, v8: process.versions.v8,
    platform: platform(), arch: arch(), osRelease: release(), cpu: cpus()[0]?.model ?? null, logicalCpuCount: cpus().length, totalMemoryBytes: totalmem(),
    childScript: CHILD_SCRIPT_PATH, retry: retryConditions, b2c2aStage1: c2a.PHASE2C26B2C2A_STAGE1, tasksBudgetMs: c2a.PHASE2C26B2C2A_TASKS_BUDGET_MS,
    contextBudget: c2a.PHASE2C26B2C2A_CONTEXT_BUDGET, validationTargets: c2a.PHASE2C26B2C2A_VALIDATION_TARGETS, expectedTasks: c2a.PHASE2C26B2C2A_EXPECTED_TASKS,
    expectedRetryTasks: r1.PHASE2C26B2C2AR1_EXPECTED_RETRY_TASKS, maxCostCohorts: c2a.PHASE2C26B2C2A_MAX_COST_COHORTS, candidateSafetyCap: c2a.PHASE2C26B2C2A_CANDIDATE_SAFETY_CAP,
    capturePrefixes: c2a.PHASE2C26B2C2A_CAPTURE_PREFIXES, extentLabel: c2a.PHASE2C26B2C2A_EXTENT_LABEL, memorySampleIntervalMs: c2a.PHASE2C26B2C2A_MEMORY_SAMPLE_INTERVAL_MS,
    nodeYield: c2a.PHASE2C26B2C2A_NODE_YIELD, notRun: [...r1.PHASE2C26B2C2AR1_NOT_RUN], registeredP1: c2a.PHASE2C26B2C2A_REGISTERED_P1,
    oracleGuidedPolicySelection: true, oracleGuidedTargetPopulation: true, contextOrderingUsesOracle: false, retrySelectionUsesOracle: false, oracleReadBySearchChild: false, oracleMatchUsedForEarlyStop: false,
    repositoryHead: git('rev-parse', 'HEAD'), uncommittedBenchmarkCode: uncommitted, benchmarkCodeSha256,
    exportFileName: basename(exportPath), exportSha256: sha256(rawExport), exportBytes: rawExport.length, rngEngineVersion: new ProductionRngEngine().version,
    targetManifestFileName: basename(targetsPath), targetManifestSha256: sha256(rawTargets), targetManifestBytes: rawTargets.length,
    retryManifestFileName: basename(retryPath), retryManifestSha256: sha256(rawRetry), retryManifestBytes: rawRetry.length, retrySourceB2C2AResultSha256: retry.sourceB2C2AResultSha256,
    smoke: smoke ? { budgetMs: smokeBudgetMs, taskIds: smokeTaskIds } : null }
  const base = { phase: 'Issue #154 Phase 2-C2.6-B2-C2A-R1: B2-C2A timeout subset searched again (Node Research run, raw)',
    measuredAt: new Date().toISOString(), environment, targetWeaponIds: targets.targetWeaponIds, retryTaskIds: retry.taskIds }

  // 1. Task reconstruction (no Search) by the unchanged B2-C2A tasks child. The child gets the Target IDs only.
  const tasksRun = await runChild('tasks', 'tasks', { targetWeaponIds: targets.targetWeaponIds }, { heapMb: retryConditions.childHeapMb, budgetMs: c2a.PHASE2C26B2C2A_TASKS_BUDGET_MS })
  if (!tasksRun.record) {
    await write(outputPath, { ...base, status: 'tasks_failed', processes, wallMs: performance.now() - phaseStarted })
    throw new Error('The tasks child failed; no Search was run.')
  }
  const construction = tasksRun.record.result.construction
  const tasksChild = { process: tasksRun.entry, recordFile: tasksRun.recordFile, childWallMs: tasksRun.record.wallMs, scheduleMs: tasksRun.record.scheduleMs, memory: tasksRun.record.memory,
    researchMaxPlanSteps: tasksRun.record.researchMaxPlanSteps, calculationContext: tasksRun.record.calculationContext, rngEngineVersion: tasksRun.record.rngEngineVersion,
    scheduleSummary: tasksRun.record.result.scheduleSummary, construction: { valid: construction.valid, issues: construction.issues } }
  // 2. Gate: exactly 20 x 16 tasks, then exactly the retry tasks.
  const tasks = construction.tasks
  const selection = r1.selectPhase2C26B2C2AR1Tasks(construction, retry.taskIds)
  const gateIssues = [...selection.issues]
  if (tasks.length !== c2a.PHASE2C26B2C2A_EXPECTED_TASKS) gateIssues.push(`${tasks.length} tasks, not ${c2a.PHASE2C26B2C2A_EXPECTED_TASKS}`)
  console.log(`tasks: ${tasks.length}; retry ${selection.tasks.length} / ${tasks.length}; gate ${gateIssues.length === 0 ? 'ok' : gateIssues.join('; ')}`)
  if (gateIssues.length > 0) {
    await write(outputPath, { ...base, status: 'task_selection_failed', gateIssues, tasksChild, processes, wallMs: performance.now() - phaseStarted })
    throw new Error(`Task reconstruction / selection failed; no Search was run: ${gateIssues.join('; ')}`)
  }
  const retryTasks = smokeTaskIds !== null ? selection.tasks.filter(t => smokeTaskIds.includes(t.taskId)) : selection.tasks

  // 3. Retry (concurrency 1: one task after the other; no second retry, no fallback).
  const retryRuns = []
  for (const task of retryTasks) {
    const run = await runChild(`r1-${task.taskId}`, 'search', task, { heapMb: retryConditions.childHeapMb, budgetMs: retryConditions.budgetMs })
    const result = run.record?.result ?? null
    const outcome = c2a.phase2c26b2c2aTaskOutcome(task.taskId, run.entry.outcome, result)
    retryRuns.push({ taskId: task.taskId, task, outcome,
      process: { outcome: run.entry.outcome, wallMs: run.entry.wallMs, timedOut: run.entry.timedOut, budgetMs: run.entry.budgetMs, exitCode: run.entry.exitCode, stderrTail: run.entry.stderrTail },
      recordFile: run.recordFile, childWallMs: run.record?.wallMs ?? null, scheduleMs: run.record?.scheduleMs ?? null, yields: run.record?.yields ?? run.entry.lastIpcYields ?? null,
      memory: run.record?.memory ?? null, lastIpcMemory: run.entry.lastIpcMemory, calculationContext: run.record?.calculationContext ?? null,
      researchMaxPlanSteps: run.record?.researchMaxPlanSteps ?? null, rngEngineVersion: run.record?.rngEngineVersion ?? null,
      contextMismatchIssues: result?.status === 'context_mismatch' ? result.issues : null,
      capture: result?.status === 'searched' ? { termination: result.search.termination, candidateCount: result.search.candidates.length, capturedCosts: result.search.capturedCosts,
        captureComplete: result.search.captureComplete, safetyCapHit: result.search.safetyCapHit, elapsedMs: result.search.elapsedMs } : null })
  }

  const record = { ...base, status: 'completed', tasksChild, tasks, selectedTasks: selection.tasks, retryRuns, processes, wallMs: performance.now() - phaseStarted }
  await write(outputPath, record)
  const count = predicate => retryRuns.filter(predicate).length
  console.log(JSON.stringify({ output: resolve(outputPath), tasks: tasks.length,
    retry: { runs: retryRuns.length, searched: count(r => r.outcome.record === 'searched'), timeout: count(r => r.outcome.process === 'timeout'),
      out_of_memory: count(r => r.outcome.process === 'out_of_memory'), process_failure: count(r => r.outcome.process === 'process_failure'),
      context_mismatch: count(r => r.outcome.record === 'context_mismatch'), safety_cap: count(r => r.capture?.safetyCapHit === true) }, wallMs: record.wallMs }, null, 2))
} finally {
  await server.close()
}
